package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Employee struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Salary   string `json:"salary,omitempty"`
	SSN      string `json:"ssn,omitempty"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// handleSearch allows searching employees by department
func handleSearch(w http.ResponseWriter, r *http.Request) {
	dept := r.URL.Query().Get("dept")
	if dept == "" {
		http.Error(w, "dept parameter required", http.StatusBadRequest)
		return
	}

	// Basic length check
	if len(dept) > 64 {
		http.Error(w, "parameter too long", http.StatusBadRequest)
		return
	}

	// Build query - vulnerable to SQL injection
	query := fmt.Sprintf(
		"SELECT id, name, email, dept_code FROM hr.employees WHERE dept_code = '%s' AND active = true",
		dept,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Employee
	for rows.Next() {
		var emp Employee
		if err := rows.Scan(&emp.ID, &emp.Name, &emp.Email, &emp.DeptCode); err != nil {
			continue
		}
		results = append(results, emp)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// handleProfile returns current user profile from JWT claims
func handleProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID") // Set by auth proxy
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var emp Employee
	err := db.QueryRow(
		"SELECT id, name, email, salary, dept_code FROM hr.employees WHERE id = $1",
		userID,
	).Scan(&emp.ID, &emp.Name, &emp.Email, &emp.Salary, &emp.DeptCode)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(emp)
}

// handleHealthCheck for ALB target group health checks
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// handleMetrics exposes internal metrics - restricted by middleware
func handleMetrics(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Metrics-Token")
	expected := os.Getenv("METRICS_TOKEN")
	if !strings.EqualFold(token, expected) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	stats := db.Stats()
	json.NewEncoder(w).Encode(stats)
}

func main() {
	http.HandleFunc("/api/search", handleSearch)
	http.HandleFunc("/api/profile", handleProfile)
	http.HandleFunc("/health", handleHealthCheck)
	http.HandleFunc("/internal/metrics", handleMetrics)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
